import styled from '@emotion/styled';
import { Card, Heading } from 'components/UI';

export const StyledCategoryGrowthLeversCard = styled(Card)({
  display: 'flex',
  flexDirection: 'row',
  border: '1px solid #e2e2e2',
  boxShadow: 'none !important',
  width: '330px',
  height: '195px',
});

interface GrowthLeversContainerProps {
  $borderBottom?: boolean;
  $borderRight?: boolean;
}

export const GrowthLeversContainer = styled('div', {
  shouldForwardProp: (propName) =>
    !['$borderBottom', '$borderRight'].includes(propName),
})<GrowthLeversContainerProps>(({ $borderBottom, $borderRight }) => ({
  display: 'flex',
  width: '100%',
  ...($borderBottom === true && {
    borderBottom: '1px solid #E5E5E5',
  }),
  ...($borderBottom === false && {
    borderBottom: 'none',
  }),
  ...($borderRight === true && {
    borderRight: '1px solid #E5E5E5',
  }),
  ...($borderRight === false && {
    borderRight: 'none',
  }),
}));

export const CategoryTitle = styled(Heading)({
  fontSize: '1rem !important',
  color: '#5C5C5C !important',
  marginTop: '8px',
});

export const ImageContainer = styled.div({
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '90px',
  height: '90px',
});

interface LeftContainerProps {
  $showImage?: boolean;
}

export const LeftContainer = styled('div', {
  shouldForwardProp: (propName) => propName !== '$showImage',
})<LeftContainerProps>(({ $showImage = true }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  borderRight: '1px solid #e2e2e2',
  height: '100%',
  width: $showImage ? '160px' : '200px',
}));

export const RightContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  flexGrow: 1,
});
